"""Generate docs/rule-catalogue.md from the live rules + English wording (prevents drift)."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
from app.rules.engine import RULES  # noqa: E402
from app.explain.templates.en import T  # noqa: E402

out = ["# Rule catalogue", "",
       "_Generated by `python scripts/gen_rule_catalogue.py` from the code. Do not edit by hand._", "",
       "Weights are hand-set heuristics that add up to a 0-100 score. They are **not** calibrated probabilities. "
       "Bands: Low < 20, Needs verification 20-44, High 45-69, Critical >= 70. A rule with `forces` sets a minimum band on its own. "
       "`quote-prone` rules are down-weighted (and quoted phrases removed) when the message is clearly a warning or awareness post.", "",
       "| Rule | Group | Weight | Severity | Forces band | Quote-prone | What the user is told |",
       "|---|---|---|---|---|---|---|"]
for r in RULES:
    title, why = T["rules"].get(r.id, ("", ""))
    out.append(f"| `{r.id}` | {r.group} | {r.weight} | {r.severity} | {r.forces or '-'} | {'yes' if r.quote_prone else '-'} | **{title}.** {why} |")
out += ["", "Plus one combination finding, `COMBO_PROMISE_PLUS_PAYMENT` (+10): a profit promise together with a request to pay.", ""]
(ROOT / "docs/rule-catalogue.md").write_text("\n".join(out), encoding="utf-8")
print("ok", len(RULES))
